/** Другое написание того же и обёртки, которым логичнее взять знак основы. */
const techAliases: Record<string, string> = {
  'backbone.js': 'backbone',
  'framer-motion': 'framer motion',
  'msw': 'mock service worker',
  'next': 'next.js',
  'nextjs': 'next.js',
  'node': 'node.js',
  'react hook form': 'react hook form',
  'react testing library': 'testing library',
  'react window': 'react',
  'react-hook-form': 'react hook form',
  'react-leaflet': 'leaflet',
  'react-router': 'react router',
  'rtk query': 'redux toolkit',
  'scss modules': 'sass',
  'tailwind css': 'tailwind',
  'tanstack router': 'tanstack',
}

function lookup(key: string): TechIcon | undefined {
  return techIcons[key] ?? techIcons[techAliases[key] ?? '']
}

export function techIcon(name: string): TechIcon | undefined {
  const key = name.trim().toLowerCase()
  return lookup(key) ?? lookup(key.replace(/\s+\d+(\.\d+)*$/, ''))
}
